"""Visual servo utilities for the single live RoboCasa PrepareCoffee episode."""
import json
from pathlib import Path
import numpy as np
from rcb_client import Robot

R=Robot()
S=R.spec()
CAMS=list(S['cameras'])
RUNS=Path('/app/runs')

def action(dx=0,dy=0,dz=0,drx=0,dry=0,drz=0,grip=-1,bx=0,by=0,byaw=0,torso=0,mode=-1):
    return np.array([dx,dy,dz,drx,dry,drz,grip,bx,by,byaw,torso,mode],dtype=np.float64)

def step(a,n=1,name=None,cameras=None,depth=True):
    acts=np.tile(np.asarray(a,dtype=np.float64),(n,1)) if np.asarray(a).ndim==1 else np.asarray(a,dtype=np.float64)
    obs=R.submit('ee_delta',acts,interpolate='hold',cameras=cameras or CAMS,include_depth=depth,video='none',note=name or '')
    if name: obs.save(str(RUNS/name))
    print(json.dumps({'name':name,'steps':obs.meta.get('control_steps'),'time_left_s':obs.meta.get('time_left_s'),'eef':eef(obs),'base':base(obs),'finger':finger(obs)}))
    return obs

def see(name=None,cameras=None,depth=True):
    obs=R.get_obs(cameras=cameras or CAMS,include_depth=depth,video='none')
    if name: obs.save(str(RUNS/name))
    print(json.dumps({'name':name,'steps':obs.meta.get('control_steps'),'time_left_s':obs.meta.get('time_left_s'),'eef':eef(obs),'base':base(obs),'finger':finger(obs)}))
    return obs

def proprio(obs):
    p=obs.meta['proprio']; return dict(zip(p['layout'],p['now']))

def eef(obs):
    p=proprio(obs); return [p['eef_right_'+a] for a in 'xyz']

def base(obs):
    p=proprio(obs);return [p['mobilebase0_joint_mobile_'+a+'_pos'] for a in ['forward','side','yaw']]

def finger(obs):
    p=proprio(obs);return [p['gripper0_right_finger_joint1_pos'],p['gripper0_right_finger_joint2_pos']]

def point(obs,cam,u,v):
    c=obs.meta['cameras'][cam]; K=np.asarray(c['intrinsic_cv']);T=np.asarray(c['cam2world_gl']);z=float(obs.depth[cam][-1,v,u]);return (T@np.array([(u-K[0,2])/K[0,0]*z,-(v-K[1,2])/K[1,1]*z,-z,1]))[:3]

if __name__=='__main__':
    import sys
    cmd=sys.argv[1] if len(sys.argv)>1 else 'see'
    if cmd=='see':see(sys.argv[2] if len(sys.argv)>2 else None)
    elif cmd=='step':
        name=sys.argv[2];n=int(sys.argv[3]);a=np.array([float(x) for x in sys.argv[4:]],dtype=np.float64)
        if len(a)!=12:raise ValueError('Need 12 action channels')
        step(a,n,name)
